package com.example.pmmovil.data.printing

import com.example.pmmovil.data.model.EntradaFormSnapshot
import java.time.LocalDate
import java.time.format.DateTimeFormatter
import java.util.Locale
import kotlin.math.roundToInt

/**
 * Genera ZPL puro para Zebra ZT411 300dpi.
 *
 * Cambios rapidos:
 * - Velocidad y oscuridad: se respetan las preferencias de la Zebra seleccionada.
 * - Tamano etiqueta: LABEL_WIDTH_DOTS y LABEL_HEIGHT_DOTS.
 * - Coordenadas: campos ^FO dentro de buildSingleLabel().
 *
 * La etiqueta fisica mide 1200 x 1800 dots a 300 dpi (4" x 6").
 * El diseno se imprime girado (^FWB).
 * Por eso la mayoria de textos usan ^A0B: al despegar la etiqueta y verla
 * horizontal, el logo queda arriba, el QR a la derecha y el parcial abajo a la derecha.
 */
object ZebraZplBuilder {
    // 300 dpi — 4" × 6" label (1200 × 1800 dots)
    const val LABEL_WIDTH_DOTS: Int = 1200
    const val LABEL_HEIGHT_DOTS: Int = 1800

    private val arrivalDateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy", Locale.forLanguageTag("es-MX"))

    private const val IMEX_LOGO_ZPL_GF = "^GFA,11040,11040,24,"



    fun buildLabels(
        labels: List<ZebraLabelData>,
        layout: ZebraLabelLayout = ZebraLabelLayout.reference()
    ): String {
        return labels.joinToString(separator = "\n") { buildSingleLabel(it, layout) }
    }

    fun buildTestLabel(): ZebraLabelData {
        val date = LocalDate.now().format(arrivalDateFormatter)
        return ZebraLabelData(
            numeroEntrada = "356398-00",
            fechaArribo = date,
            cliente = "PERSONAL CLIENTES",
            caja = "PMM-TEST",
            guia = "OFNA",
            ubicaciones = "PRUEBA",
            qrValue = "PMMOVIL-ZPL-TEST-${System.currentTimeMillis()}",
            parcial = "1/1",
            tipoEtiqueta = "PRUEBA"
        )
    }

    fun fromEntradaForm(form: EntradaFormSnapshot): List<ZebraLabelData> {
        val reference = form.referenceRaw()
        val displayReference = form.labelReferenceDisplay()
        val date = form.fecha.toArrivalDate()
        val customer = listOf(form.nomCliente.trim(), form.codCliente.trim())
            .filter { it.isNotBlank() }
            .joinToString("")
        val locations = form.detalles
            .map { it.ubicacion.trim() }
            .filter(String::isNotBlank)
            .distinct()
            .joinToString(", ")
        val totalPackages = maxOf(1, form.detalles.sumOf { it.cantidad }.roundToInt())

        return buildList(capacity = totalPackages + 1) {
            add(
                ZebraLabelData(
                    numeroEntrada = displayReference,
                    fechaArribo = date,
                    cliente = customer,
                    caja = form.cajaArribo,
                    guia = form.guia,
                    ubicaciones = locations,
                    qrValue = reference,
                    tipoEtiqueta = "CARPETA"
                )
            )
            for (index in 1..totalPackages) {
                add(
                    ZebraLabelData(
                        numeroEntrada = displayReference,
                        fechaArribo = date,
                        cliente = customer,
                        caja = form.cajaArribo,
                        guia = form.guia,
                        ubicaciones = locations,
                        qrValue = "$reference $index-$totalPackages",
                        parcial = "$index/$totalPackages"
                    )
                )
            }
        }
    }

    private fun buildSingleLabel(
        label: ZebraLabelData,
        layout: ZebraLabelLayout
    ): String {
        val copies = label.copies.coerceAtLeast(1)
        val isCarpeta = label.tipoEtiqueta.equals("CARPETA", ignoreCase = true)
        val counterText = if (isCarpeta) "CARPETA" else label.parcial
        val safeCounterText = counterText.zplText(18)
        val counter = layout.counter
        val counterFontHeight = if (isCarpeta) {
            (counter.fontHeight * 0.28f).roundToInt().coerceAtLeast(70)
        } else {
            counter.fontHeight
        }
        val counterFontWidth = if (isCarpeta) {
            (counter.fontWidth * 0.28f).roundToInt().coerceAtLeast(62)
        } else {
            counter.fontWidth
        }
        val counterElement = if (isCarpeta) {
            counter.copy(
                x = (counter.x - 180).coerceAtLeast(0),
                y = ZebraLabelLayout.READING_HEIGHT_DOTS - 70,
                width = (counter.width + 180).coerceAtMost(ZebraLabelLayout.READING_WIDTH_DOTS)
            )
        } else {
            counter
        }

        return """
            ^XA
            ^CI28
            ^PW$LABEL_WIDTH_DOTS
            ^LL$LABEL_HEIGHT_DOTS
            ^LH0,0

            ^FWB
            ${logoZpl(layout.logo)}
            ^FWN

            ${qrZpl(layout.qr, label.qrValue.zplQr())}

            ${textZpl(layout.arrivalLabel, "F. ARRIBO:")}
            ${textZpl(layout.arrivalDate, label.fechaArribo.zplText(20))}
            ${underlineZpl(layout.arrivalDate)}

            ${referenceZpl(layout.reference, label.numeroEntrada)}

            ${textZpl(layout.customerLabel, "CLIENTE:")}
            ${textZpl(layout.customerValue, label.cliente.zplText(70))}
            ${underlineZpl(layout.customerValue)}

            ${textZpl(layout.boxLabel, "CAJA:")}
            ${textZpl(layout.boxValue, label.caja.zplText(40))}
            ${underlineZpl(layout.boxValue)}

            ${textZpl(layout.guideLabel, "GUIA:")}
            ${textZpl(layout.guideValue, label.guia.zplText(150))}
            ${underlineZpl(layout.guideValue)}

            ${textZpl(layout.locationLabel, "UBICA:")}
            ${textZpl(layout.locationValue, label.ubicaciones.zplText(70))}
            ${underlineZpl(layout.locationValue)}

            ${textZpl(
                element = counterElement.copy(fontHeight = counterFontHeight, fontWidth = counterFontWidth),
                value = safeCounterText,
                alignment = "R"
            )}
            ^PQ$copies
            ^XZ
        """.trimIndent()
    }

    private fun logoZpl(element: ZebraLabelElement): String {
        val y = (LABEL_HEIGHT_DOTS - element.x - element.width).coerceAtLeast(0)
        return "^FO${element.y},$y$IMEX_LOGO_ZPL_GF^FS"
    }

    private fun qrZpl(element: ZebraLabelElement, value: String): String {
        val qrRight = (element.x + element.width).coerceAtMost(LABEL_HEIGHT_DOTS)
        val y = (LABEL_HEIGHT_DOTS - qrRight).coerceAtLeast(0)
        val magnification = element.fontHeight.coerceIn(2, 30)
        return "^FO${element.y},$y^BQN,2,$magnification^FDLA,$value^FS"
    }

    private fun textZpl(
        element: ZebraLabelElement,
        value: String,
        alignment: String = "L"
    ): String {
        val y = (LABEL_HEIGHT_DOTS - element.x - element.width).coerceAtLeast(0)
        val fontHeight = element.fontHeight.coerceAtLeast(12)
        val fontWidth = element.fontWidth.coerceAtLeast(10)
        return "^FO${element.y},$y^A0B,$fontHeight,$fontWidth^FB${element.width},1,0,$alignment,0^FD$value^FS"
    }

    private fun underlineZpl(element: ZebraLabelElement): String {
        val lineY = (LABEL_HEIGHT_DOTS - element.x - element.width).coerceAtLeast(0)
        val lineX = (element.y + element.height).coerceAtMost(LABEL_WIDTH_DOTS - 3)
        return "^FO$lineX,$lineY^GB3,${element.width},3^FS"
    }

    /** Dibuja el guion como barra para evitar el espacio visual excesivo de la fuente Zebra. */
    private fun referenceZpl(element: ZebraLabelElement, numero: String): String {
        val clean = numero.zplText(16)
        val dash = clean.indexOf('-')
        if (dash <= 0 || dash >= clean.length - 1) {
            return textZpl(element, clean)
        }
        val consecutive = clean.substring(0, dash)
        val suffix = clean.substring(dash + 1)
        val glyphAdvance = (element.fontWidth * 0.72f).roundToInt().coerceAtLeast(24)
        val consecutiveWidth = (consecutive.length * glyphAdvance + 12)
            .coerceAtMost(element.width - 120)
        val dashX = element.x + consecutiveWidth + 12
        val suffixX = dashX + 82
        val suffixWidth = (element.width - (suffixX - element.x)).coerceAtLeast(80)
        val dashPrintY = (LABEL_HEIGHT_DOTS - dashX - 44).coerceAtLeast(0)
        val dashPrintX = (element.y + element.fontHeight / 2).coerceAtMost(LABEL_WIDTH_DOTS - 24)

        return textZpl(element.copy(width = consecutiveWidth), consecutive) +
            "^FO$dashPrintX,$dashPrintY^GB24,44,24^FS" +
            textZpl(element.copy(x = suffixX, width = suffixWidth), suffix)
    }

    private fun EntradaFormSnapshot.referenceRaw(): String =
        "$ref1$ref2$ref3$ref4$ref5$ref6"

    private fun EntradaFormSnapshot.labelReferenceDisplay(): String {
        val consecutive = ref4.trim()
        if (consecutive.isBlank()) return ""
        val suffix = ref5.trim()
            .ifBlank { referenceRaw().dropLast(2).takeLast(2) }
            .ifBlank { "00" }
            .padStart(2, '0')
            .takeLast(2)
        return "$consecutive-$suffix"
    }

    private fun String.toArrivalDate(): String {
        val clean = trim()
        if (clean.isBlank()) return ""
        val datePart = clean.take(10)
        return runCatching {
            LocalDate.parse(datePart).format(arrivalDateFormatter)
        }.getOrDefault(datePart)
    }

    private fun String.zplText(maxLength: Int): String =
        sanitizeForZpl()
            .take(maxLength)

    private fun String.zplQr(): String =
        sanitizeForZpl()
            .take(700)

    private fun String.sanitizeForZpl(): String {
        return asSequence()
            .map { char ->
                when {
                    char == '^' || char == '~' || char == '\u0000' -> ' '
                    char.code < 32 -> ' '
                    else -> char
                }
            }
            .joinToString(separator = "")
            .replace(Regex("\\s+"), " ")
            .trim()
    }
}
